public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) return 0;
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    for (int i=0;i<rows;i++){
        for (int j=0;j<cols;j++){
            if (grid[i][j]=='@' && !visited[i][j]){
                count++;
                dfs(grid, visited, i, j, rows, cols);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int x, int y, int rows, int cols){
    visited[x][y] = true;
    int[] dx = {-1,-1,-1,0,0,1,1,1};
    int[] dy = {-1,0,1,-1,1,-1,0,1};
    for (int dir=0;dir<8;dir++){
        int nx = x + dx[dir];
        int ny = y + dy[dir];
        if (nx>=0 && nx<rows && ny>=0 && ny<cols && grid[nx][ny]=='@' && !visited[nx][ny]){
            dfs(grid, visited, nx, ny, rows, cols);
        }
